import sys

def icici_encrypt(text):
    result = []
    for char in text:
        result.append(chr(ord(char) + 1))
        result.append('1')
    return ''.join(result)

def hdfc_encrypt(text):
    char_list = list(text)
    n = len(char_list)
    for i in range(n):
        if char_list[i] == ' ':
            continue
        if i % 2 == 0:
            char_list[i] = chr(ord(char_list[i]) + 1)
        else:
            char_list[i] = chr(ord(char_list[i]) - 1)
    return ''.join(char_list)

def main():
    line = sys.stdin.readline().rstrip('\n')
    if not line:
        return
    parts = line.split(' ', 1)
    bank_type = int(parts[0])
    message = parts[1] if len(parts) > 1 else ''

    if bank_type == 1:
        encrypted = icici_encrypt(message)
    elif bank_type == 2:
        encrypted = hdfc_encrypt(message)
    else:
        encrypted = ''

    sys.stdout.write(encrypted + '\n')

if __name__ == "__main__":
    main()
